func (q *Queries) DueTuitions(ctx context.Context, arg DueTuitionsParams) ([]DueTuitionsRow, error) {
	rows, err := q.db.Query(ctx, dueTuitions,
		arg.Until,
		arg.Today,
		arg.BranchIds,
		arg.Search,
		arg.BranchID,
		arg.ClassID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DueTuitionsRow
	for rows.Next() {
		var i DueTuitionsRow
		if err := rows.Scan(
			&i.ID,
			&i.StudentID,
			&i.ClassID,
			&i.BranchID,
			&i.BankAccountID,
			&i.PromotionID,
			&i.TotalAmount,
			&i.SessionCount,
			&i.DiscountAmount,
			&i.OtherFees,
			&i.FeeItems,
			&i.PrepaidAmount,
			&i.FinalAmount,
			&i.PaidAmount,
			&i.DebtAmount,
			&i.DueDate,
			&i.ReminderPausedUntil,
			&i.DeferredFrom,
			&i.DeferredUntil,
			&i.FrozenRemainingSessions,
			&i.FrozenDebtAmount,
			&i.Status,
			&i.Notes,
			&i.TransferMemo,
			&i.LegacyID,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StudentCode,
			&i.StudentName,
			&i.StudentPhone,
			&i.ClassName,
			&i.ClassCode,
			&i.CourseName,
			&i.BranchName,
			&i.CourseLessons,
			&i.ScheduledSessions,
			&i.AttendedSessions,
			&i.StatsClassID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const electronicRangeCandidates = `-- name: ElectronicRangeCandidates :many

SELECT id FROM finance.invoice_ranges
WHERE kind = 'electronic' AND is_active AND (branch_id = $1 OR branch_id IS NULL)
ORDER BY (branch_id IS NULL), start_number, id
`

// ───────────────────────── Dải số hóa đơn ─────────────────────────
// Dải điện tử đang dùng của chi nhánh trước, rồi dải mặc định.
func (q *Queries) ElectronicRangeCandidates(ctx context.Context, branchID *uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, electronicRangeCandidates, branchID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

