const listReceipts = `-- name: ListReceipts :many
SELECT r.id, r.code, r.source, r.invoice_number, r.tuition_id, r.student_id, r.amount, r.tuition_amount, r.session_count, r.session_unit_price, r.material_fee, r.exam_fee, r.other_fee, r.other_fee_reason, r.surcharge_amount, r.surcharge_reason, r.discount_amount, r.promotion_id, r.discount_reason, r.payment_method, r.transaction_code, r.transfer_reference, r.payer_name, r.payer_phone, r.is_vat_invoice, r.paper_invoice_number, r.proof_url, r.proof_file_id, r.payment_date, r.collected_items, r.status, r.notes, r.rejection_reason, r.creator_id, r.approver_id, r.approved_at, r.deposited_at, r.deposited_by, r.legacy_id, r.created_at, r.updated_at, st.code AS student_code, st.full_name AS student_name, tc.name AS tuition_class_name, cc.name AS current_class_name,
    tco.name AS course_name, sb.name AS branch_name,
    jsonb_array_length(COALESCE(t.fee_items, '[]')) AS tuition_fee_item_count,
    cu.full_name AS creator_name, au.full_name AS approver_name, du.full_name AS depositor_name
FROM finance.receipts r
LEFT JOIN finance.tuitions t ON t.id = r.tuition_id
LEFT JOIN academic.students st ON st.id = COALESCE(t.student_id, r.student_id)
LEFT JOIN academic.classes cc ON cc.id = st.current_class_id
LEFT JOIN academic.classes tc ON tc.id = t.class_id
LEFT JOIN academic.courses tco ON tco.id = tc.course_id
LEFT JOIN core.branches sb ON sb.id = st.branch_id
LEFT JOIN iam.users cu ON cu.id = r.creator_id
LEFT JOIN iam.users au ON au.id = r.approver_id
LEFT JOIN iam.users du ON du.id = r.deposited_by
WHERE ($1::uuid[] IS NULL OR COALESCE(t.branch_id, st.branch_id, cc.branch_id) = ANY ($1::uuid[]))
  AND ($2::text IS NULL OR r.status = $2)
  AND ($3::text IS NULL OR r.payment_method = $3)
  AND ($4::uuid IS NULL OR st.branch_id = $4)
  AND ($5::uuid IS NULL OR COALESCE(t.student_id, r.student_id) = $5)
  AND ($6::date IS NULL OR r.payment_date >= $6)
  AND ($7::date IS NULL OR r.payment_date <= $7)
  AND (NOT $8::boolean OR (t.id IS NOT NULL AND EXISTS (
        SELECT 1 FROM finance.tuitions t0 WHERE t0.student_id = t.student_id AND (t0.created_at, t0.id) < (t.created_at, t.id))))
  AND ($9::text IS NULL OR r.code ILIKE '%' || $9 || '%'
       OR r.transaction_code ILIKE '%' || $9 || '%' OR r.payer_name ILIKE '%' || $9 || '%'
       OR r.invoice_number ILIKE '%' || $9 || '%'
       OR st.full_name ILIKE '%' || $9 || '%' OR st.code ILIKE '%' || $9 || '%')
ORDER BY r.created_at DESC, r.id DESC
LIMIT $11 OFFSET $10
`

