const listTuitions = `-- name: ListTuitions :many


SELECT t.id, t.student_id, t.class_id, t.branch_id, t.bank_account_id, t.promotion_id, t.total_amount, t.session_count, t.discount_amount, t.other_fees, t.fee_items, t.prepaid_amount, t.final_amount, t.paid_amount, t.debt_amount, t.due_date, t.reminder_paused_until, t.deferred_from, t.deferred_until, t.frozen_remaining_sessions, t.frozen_debt_amount, t.status, t.notes, t.transfer_memo, t.legacy_id, t.created_by, t.created_at, t.updated_at, s.code AS student_code, s.full_name AS student_name, s.phone AS student_phone,
    c.name AS class_name, c.code AS class_code, co.name AS course_name, b.name AS branch_name
FROM finance.tuitions t
JOIN academic.students s ON s.id = t.student_id AND s.deleted_at IS NULL
LEFT JOIN academic.classes cc ON cc.id = s.current_class_id
LEFT JOIN academic.classes c ON c.id = t.class_id
LEFT JOIN academic.courses co ON co.id = c.course_id
LEFT JOIN core.branches b ON b.id = t.branch_id
WHERE ($1::uuid[] IS NULL OR COALESCE(t.branch_id, s.branch_id, cc.branch_id) = ANY ($1::uuid[]))
  AND ($2::text IS NULL OR s.full_name ILIKE '%' || $2 || '%'
       OR s.phone ILIKE '%' || $2 || '%' OR s.code ILIKE '%' || $2 || '%')
  AND ($3::text IS NULL OR ($3 = 'overdue' AND t.debt_amount > 0 AND t.due_date < $4::date
       AND (t.reminder_paused_until IS NULL OR t.reminder_paused_until <= $4::date))
       OR ($3 <> 'overdue' AND t.status = $3))
  AND ($5::uuid IS NULL OR t.branch_id = $5)
  AND ($6::uuid IS NULL OR t.class_id = $6)
ORDER BY t.created_at DESC, t.id DESC
LIMIT $8 OFFSET $7
`

